/**
 * presets.js
 * Matches plain words typed in the "X" field against a slimmed copy of the iD
 * editor's preset list (id-tagging-schema), so "swimming pool" can become
 * ["leisure"="swimming_pool"].
 *
 * The preset file is generated by scripts/build-presets.mjs and is fetched
 * lazily - importing this module performs no network request, so the matcher
 * can be imported in Node for tests. Each record carries a `count` (how often
 * its tags appear in OSM, from taginfo at build time, `approx` when the preset
 * has several tags), which decides the order inside a match tier. No taginfo
 * request is made at runtime for presets.
 *
 * Preset data: id-tagging-schema, (c) OpenStreetMap contributors, ISC licence.
 */

/** Same-origin location of the generated preset file, relative to index.html */
export const DEFAULT_PRESETS_URL = 'data/presets.json';

/**
 * Match tiers, lowest (best) first. Starting a word counts the same as starting
 * the name, so "Swimming Pool" competes with "Pool Supply Store" for "pool" and
 * the baked taginfo count decides which is more likely to be wanted.
 */
const TIER_NAME_EXACT = 0;
const TIER_NAME_PREFIX = 1;
const TIER_NAME_SUBSTRING = 2;
const TIER_TERM = 3;

/** How much to trust a multi-tag preset's (upper bound) count when ranking */
const APPROX_DISCOUNT = 0.5;

/**
 * Added to the tier when the match only worked after singularising the query,
 * so "castles" still finds Castle but never outranks a direct match.
 */
const PLURAL_PENALTY = 4;

/** How long to wait before trying a failed preset load again */
const RETRY_AFTER_MS = 30_000;

// Cached in-flight/settled load, so the file is fetched at most once
let presetsPromise = null;
// The records once they are here, for callers that cannot wait
let loaded = null;
// A failure is remembered for a while, so a broken load is not retried on
// every keystroke
let failedAt = 0;
let lastError = null;

/**
 * Load the generated preset list, fetching it at most once per page
 * @param {string} [url] - Override for the preset file location
 * @returns {Promise<Array<Object>>} The preset records
 */
export function loadPresets(url = DEFAULT_PRESETS_URL) {
    if (!presetsPromise && failedAt && Date.now() - failedAt < RETRY_AFTER_MS) {
        return Promise.reject(lastError);
    }

    if (!presetsPromise) {
        presetsPromise = fetch(url)
            .then(response => {
                if (!response.ok) {
                    throw new Error(`Failed to load presets: ${response.status}`);
                }
                return response.json();
            })
            .then(data => {
                loaded = Array.isArray(data) ? data : [];
                return loaded;
            })
            .catch(error => {
                // Allow a later attempt to retry, but not immediately
                presetsPromise = null;
                failedAt = Date.now();
                lastError = error;
                throw error;
            });
    }

    return presetsPromise;
}

/**
 * The presets if they have already arrived. A suggestion list must never wait
 * on this file: a stalled fetch would take the whole list down with it.
 * @returns {Array<Object>|null} The records, or null while they are not here
 */
export function peekPresets() {
    return loaded;
}

/**
 * Forget any cached preset load (used by tests)
 */
export function resetPresetCache() {
    presetsPromise = null;
    loaded = null;
    failedAt = 0;
    lastError = null;
}

/**
 * Decide which element types a preset's geometry implies
 * @param {Array<string>} geometry - iD geometry list ('point', 'line', 'area', 'vertex', 'relation')
 * @returns {string} 'way' for line-only presets, otherwise 'wr'
 */
export function elementTypesForGeometry(geometry) {
    const geometries = Array.isArray(geometry) ? geometry : [];

    if (geometries.includes('area') || geometries.includes('relation')) {
        return 'wr';
    }
    if (geometries.includes('line')) {
        return 'way';
    }
    return 'wr';
}

/**
 * Convert a preset's tags into tagParser-style filters
 * @param {Object} preset - A preset record
 * @returns {Array<Object>} Filters ready for queryBuilder
 */
export function presetToFilters(preset) {
    const tags = (preset && preset.tags) || {};

    return Object.entries(tags).map(([key, value]) => (
        value === '*'
            ? { key, op: 'exists' }
            : { key, op: '=', value: String(value) }
    ));
}

/**
 * Summarise a preset's tags as an expression, for the secondary text of a
 * suggestion row. Several presets share a display name ("School" is both
 * amenity=school and building=school), so the tags are what tells them apart.
 * @param {Object} preset - A preset record
 * @returns {string} Something like 'amenity=school' or 'building=*'
 */
export function presetTagSummary(preset) {
    const tags = (preset && preset.tags) || {};

    return Object.entries(tags)
        .map(([key, value]) => `${key}=${value}`)
        .join(' ');
}

/**
 * The count to sort a preset by. A multi-tag preset's count is the count of its
 * rarest tag, so the real number can only be lower - discount it a little so a
 * single-tag preset of similar size is preferred.
 * @param {Object} preset - A preset record
 * @returns {number} The count to compare by
 */
function rankingCount(preset) {
    const count = Number(preset.count) || 0;
    return preset.approx ? count * APPROX_DISCOUNT : count;
}

/**
 * Check whether any word of a name starts with the query
 * @param {string} name - Lower-cased preset name
 * @param {string} query - Lower-cased query
 * @returns {boolean} True when a word boundary matches
 */
function hasWordPrefix(name, query) {
    let index = name.indexOf(query);

    while (index > 0) {
        if (!/[A-Za-z0-9]/.test(name[index - 1])) {
            return true;
        }
        index = name.indexOf(query, index + 1);
    }

    return false;
}

/**
 * Strip a simple English plural from each word, so "castles" finds Castle and
 * "golf courses" finds Golf Course
 * @param {string} query - Lower-cased query
 * @returns {string} The singularised query
 */
export function singularise(query) {
    return String(query ?? '')
        .split(' ')
        .map(word => {
            if (word.length > 3 && word.endsWith('ies')) {
                return `${word.slice(0, -3)}y`;
            }
            if (word.length > 3 && /(ch|sh|ss|x|z)es$/.test(word)) {
                return word.slice(0, -2);
            }
            if (word.length > 3 && word.endsWith('s') && !word.endsWith('ss')) {
                return word.slice(0, -1);
            }
            return word;
        })
        .join(' ');
}

/**
 * Score a preset against a query, falling back to the singular form
 * @param {Object} preset - A preset record
 * @param {string} query - Lower-cased, trimmed query
 * @param {string} singular - The singularised query
 * @returns {number|null} The tier (lower is better), or null when it does not match
 */
function scorePreset(preset, query, singular) {
    const direct = scoreAgainst(preset, query);

    if (direct !== null || singular === query) {
        return direct;
    }

    const plural = scoreAgainst(preset, singular);
    return plural === null ? null : plural + PLURAL_PENALTY;
}

/**
 * Score a single preset against one spelling of the query
 * @param {Object} preset - A preset record
 * @param {string} query - Lower-cased, trimmed query
 * @returns {number|null} The tier, or null when it does not match
 */
function scoreAgainst(preset, query) {
    if (!preset) {
        return null;
    }

    const name = String(preset.name || '').toLowerCase();

    if (name) {
        if (name === query) return TIER_NAME_EXACT;
        if (name.startsWith(query) || hasWordPrefix(name, query)) return TIER_NAME_PREFIX;
        if (name.includes(query)) return TIER_NAME_SUBSTRING;
    }

    for (const rawTerm of preset.terms || []) {
        if (String(rawTerm).toLowerCase().includes(query)) {
            return TIER_TERM;
        }
    }

    return null;
}

/**
 * Rank presets against typed text: exact name, then names (or words of names)
 * starting with it, then names containing it, then search terms. Inside a tier
 * the most used tag comes first, then the shorter name.
 * @param {Array<Object>} presets - Preset records (from loadPresets)
 * @param {string} query - The typed text
 * @param {Object} [options] - Matching options
 * @param {number} [options.limit] - Maximum number of results (default 8)
 * @returns {Array<Object>} Matching presets, best first
 */
export function matchPresets(presets, query, options = {}) {
    const limit = options.limit === undefined ? 8 : options.limit;
    const needle = String(query ?? '').trim().replace(/\s+/g, ' ').toLowerCase();

    if (!Array.isArray(presets) || needle === '') {
        return [];
    }

    const scored = [];
    const singular = singularise(needle);

    presets.forEach((preset, index) => {
        const score = scorePreset(preset, needle, singular);
        if (score !== null) {
            scored.push({ preset, score, index });
        }
    });

    scored.sort((a, b) => {
        if (a.score !== b.score) {
            return a.score - b.score;
        }

        // Inside a tier the tag people actually use wins
        const countA = rankingCount(a.preset);
        const countB = rankingCount(b.preset);
        if (countA !== countB) {
            return countB - countA;
        }

        const nameA = String(a.preset.name || '');
        const nameB = String(b.preset.name || '');

        if (nameA.length !== nameB.length) {
            return nameA.length - nameB.length;
        }
        if (nameA !== nameB) {
            return nameA < nameB ? -1 : 1;
        }
        return a.index - b.index;
    });

    const matches = scored.map(entry => entry.preset);
    return limit === Infinity ? matches : matches.slice(0, limit);
}
